import{_ as s,a0 as r,w as l,s as d,ao as a,I as n,x as e,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux 有问必答：在 Linux 上如何通过命令行来更改日期和时间 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：在 Linux 上如何通过命令行来更改日期和时间 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：在 Linux 上如何通过命令行来更改日期和时间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：在 Linux 上如何通过命令行来更改日期和时间 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141014 Linux FAQs with Answers--How to change date and time from the command line on Linux","title":"Linux 有问必答：在 Linux 上如何通过命令行来更改日期和时间","tag":"201411","desc":""},"relativePath":"201411/20141014 Linux FAQs with Answers--How to change date and time from the command line on Linux.md","filePath":"[post].md"}'),u={name:"201411/20141014 Linux FAQs with Answers--How to change date and time from the command line on Linux.md"};function m(x,t,T,L,f,g){const o=r("Link");return l(),d("div",null,[t[20]||(t[20]=a(`<h1 id="linux-有问必答-在-linux-上如何通过命令行来更改日期和时间" tabindex="-1">Linux 有问必答：在 Linux 上如何通过命令行来更改日期和时间 <a class="header-anchor" href="#linux-有问必答-在-linux-上如何通过命令行来更改日期和时间" aria-label="Permalink to “Linux 有问必答：在 Linux 上如何通过命令行来更改日期和时间”">​</a></h1><blockquote><p><strong>问题</strong>: 在 Linux 上, 我怎样通过命令行来改变日期和时间?</p></blockquote><p>在 Linux 系统中保持日期和时间的同步是每一个 Linux 用户和系统管理员的重要责任. 很多程序都依靠精确的时间信息得以正常工作. 另外, 不精确的日期和时间会使得日志文件中的时间戳变得毫无意义, 减弱了它们在系统检查和检修中的作用. 对于生产系统来说, 精确的日期和时间甚至更为重要. 例如, 在零售公司中, 所有产品必须时刻准确地计数(并储存在数据库服务器中)以便于财政部门计算每天及每周,每月,每年的支出和收入.</p><p>我们必须注意, 在 Linux 机器上有两种时钟: 由内核维持的软件时钟(又称系统时钟)和在机器关机后记录时间的(电池供电的)硬件时钟. 启动的时候, 内核会把系统时钟与硬件时钟同步. 之后, 两个时钟各自独立运行.</p><h3 id="方法一-date-命令" tabindex="-1">方法一: Date 命令 <a class="header-anchor" href="#方法一-date-命令" aria-label="Permalink to “方法一: Date 命令”">​</a></h3><p>在 Linux 中, 你可以通过 date 命令来更改系统的日期和时间:</p><pre><code># date --set=&#39;NEW_DATE&#39; 
</code></pre><p>其中 NEW_DATE 是诸如 &quot;Sun, 28 Sep 2014 16:21:42&quot; 或者 &quot;2014-09-29 16:21:42&quot; 的可读格式的日期字符串.</p><p>日期格式也可以手动指定以获得更精确的结果:</p><pre><code># date +FORMAT --set=&#39;NEW_DATE&#39; 
</code></pre><p>例如:</p><pre><code># date +’%Y%m%d %H%m’ --set=&#39;20140928 1518&#39; 
</code></pre><p><img src="https://farm3.staticflickr.com/2944/15220890657_858528a186_o.png" alt=""></p><p>你也可以用相对的方式地增加或减少一定的天数,周数,月数和秒数,分钟数,小时数。 你也可以把日期和时间的参数放到一个命令中。</p><pre><code># date --set=&#39;+5 minutes&#39;
# date --set=&#39;-2 weeks&#39;
# date --set=&#39;+3 months&#39;
# date --set=&#39;-3 months +2 weeks -5 minutes&#39; 
</code></pre><p><img src="https://farm3.staticflickr.com/2943/15220655239_deba528dce_o.png" alt=""></p><p>最后, 把硬件时钟设置为当前系统时钟:</p><pre><code># hwclock --systohc 
</code></pre><p>运行 <strong>hwclock --systohc</strong> 的目的是将硬件时钟同软件时钟同步, 这可以更正硬件时钟的系统漂移(即时钟按照一定的速度走快或走慢).</p><p>另一方面, 如果硬件时钟是正确的, 但系统时钟有误, 可以用下面的命令更正:</p><pre><code> # hwclock --hctosys
</code></pre><p>在两种情况下, hwclock 命令都是将两个时钟同步. 否则, 重启后时间会是错误的, 因为当电源关闭时硬件时钟会记忆时间. 然而, 这对于虚拟机器并不适用, 因为虚拟机器并不能访问硬件时钟.</p>`,22)),n("p",null,[t[1]||(t[1]=e("如果你的 Linux 系统上的默认时区是错误的, 你可以按照",-1)),i(o,{href:"http://ask.xmodulo.com/change-timezone-linux.html"},{default:p(()=>[...t[0]||(t[0]=[e("这个指导",-1)])]),_:1}),t[2]||(t[2]=e("进行更正.",-1))]),t[21]||(t[21]=n("h3",{id:"方法二-ntp",tabindex:"-1"},[e("方法二: NTP "),n("a",{class:"header-anchor",href:"#方法二-ntp","aria-label":"Permalink to “方法二: NTP”"},"​")],-1)),n("p",null,[t[4]||(t[4]=e("另一种使系统日期和时间保持精确的方法是使用 NTP (网络时间协议). 在 Linux 上, ntpdate 命令通过 NTP 将系统时钟和",-1)),i(o,{href:"http://www.pool.ntp.org/"},{default:p(()=>[...t[3]||(t[3]=[e("公共 NTP 服务器",-1)])]),_:1}),t[5]||(t[5]=e("同步.",-1))]),t[22]||(t[22]=a(`<p>你可以使用如下命令来安装 <strong>ntpdate</strong>:</p><p>在 Debian 及基于 Debian 的发行版上:</p><pre><code># aptitude install ntpdate
</code></pre><p>在基于 Ret Hat 的发行版上:</p><pre><code># yum install ntpdate
</code></pre><p>使用 NTP 同步系统时钟:</p><pre><code># ntpdate -u &lt;NTP 服务器名或IP&gt;
# hwclock --systohc 
</code></pre><p><img src="https://farm4.staticflickr.com/3930/15404223021_8da3b44a62_z.jpg" alt=""></p>`,8)),n("p",null,[t[7]||(t[7]=e("除了一次性使用 ntpdate 来同步时钟, 你也可以使用 NTP 守护进程(ntpd), 它会始终在后台运行, 不断地通过 NTP 来调整系统时钟. 关于 NTP 的设置, 请参考",-1)),i(o,{href:"http://xmodulo.com/how-to-synchronize-time-with-ntp.html"},{default:p(()=>[...t[6]||(t[6]=[e("这个指导",-1)])]),_:1}),t[8]||(t[8]=e(".",-1))]),t[23]||(t[23]=n("hr",null,null,-1)),n("p",null,[t[10]||(t[10]=e("via: ",-1)),i(o,{href:"http://ask.xmodulo.com/change-date-time-command-line-linux.html"},{default:p(()=>[...t[9]||(t[9]=[e("http://ask.xmodulo.com/change-date-time-command-line-linux.html",-1)])]),_:1})]),n("p",null,[t[13]||(t[13]=e("译者：",-1)),i(o,{href:"https://github.com/wangjiezhe"},{default:p(()=>[...t[11]||(t[11]=[e("wangjiezhe",-1)])]),_:1}),t[14]||(t[14]=e(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[12]||(t[12]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[17]||(t[17]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原创翻译，",-1)),i(o,{href:"http://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[e("Linux中国",-1)])]),_:1}),t[19]||(t[19]=e(" 荣誉推出",-1))])])}const k=s(u,[["render",m]]);export{_ as __pageData,k as default};
